# cc-P678 WRITES art_gen_layout.py: cc-P237-tools/gen_layout.py with its paths pointed at Iron, its placement and
# validator this folder's (art/placement.json, art_validate.py: the SoS checks), and the generated file's header
# saying so. Each change is an exact text replacement, asserted to apply once.
import os
HERE = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(HERE, '..', '..', 'cc-P237-tools', 'gen_layout.py'), encoding='utf-8').read()
pairs = [
    ("import json, os, sys, subprocess, csv\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\n",
     "import json, os, sys, subprocess, csv\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, '..', '..', 'cc-P237-tools'))\n"),
    ("SL = 'D:/UO/golems/" + "Bronze/ShatteredLegacy'", "SL = 'D:/UO/golems/Iron/ShatteredLegacy'"),
    ("os.path.join(HERE, 'validate.py')", "os.path.join(HERE, 'art_validate.py')"),
    ("sys.exit('validate.py fails; not writing:\\n'", "sys.exit('art_validate.py fails; not writing:\\n'"),
    ("    '// GENERATED by shard-migration notes/cc-P237-tools/gen_layout.py from placement.json and registry.csv. Do not edit',\n"
     "    '// by hand: change placement.json, run validate.py (the map checks), then gen_layout.py.',\n",
     "    '// GENERATED by shard-migration notes/cc-P678-tools/art/art_gen_layout.py (cc-P237-tools/gen_layout.py on SoS) from',\n"
     "    '// art/placement.json and registry.csv. Do not edit by hand: change art_draft.py, run it, run art_validate.py (the',\n"
     "    '// SoS map checks), then art_gen_layout.py.',\n"),
    ("    '// cc-P237 (F-21): New Haven\\'s community art, one row per item, all on Trammel. Every row was checked against the',\n"
     "    '// server\\'s own map files: the surface at its z, nothing impassable in the way, off the roads (but the steps\\' railing),',\n"
     "    '// not a door, a door\\'s swing tile, a seeded tile, a pinned spawner or its ring, a pinned decoration or P188\\'s walk;',\n"
     "    '// paintings only on a north wall with no OSI wall art beside them; the orc camp outside every creature spawner\\'s',\n"
     "    '// walking box. The table with a reason per row is in the cc-P237 notes.',\n",
     "    '// cc-P237 (F-21): New Haven\\'s community art, one row per item, all on Trammel. cc-P678 moved it into the author\\'s',\n"
     "    '// Haven on the Siege of Sosaria map. Every row was checked against the SoS map files: the surface at its z, a walker',\n"
     "    '// stands there and reaches it from the start, nothing impassable in the way, off the roads (but the door\\'s railing),',\n"
     "    '// not a door, a door\\'s swing tile, a seeded tile, a pinned spawner or its ring, a pinned decoration, a HavenSpots',\n"
     "    '// spot, an NPC home or the way in to the Rootdeep hatch; paintings only on a north wall with no wall art beside them;',\n"
     "    '// the orc camp outside the town and every creature spawner\\'s walking box; no piece cuts off a tile a walker could',\n"
     "    '// reach. The table with a reason per row is notes/cc-P678-tools/art/art-validate.out.txt.',\n"),
]
for a, b in pairs:
    assert src.count(a) == 1, (a[:70], src.count(a))
    src = src.replace(a, b)
src = src.replace("rows = json.load(open(os.path.join(HERE, 'placement.json')))", "rows = json.load(open(os.path.join(HERE, 'placement.json')))  # art/placement.json (art_draft.py)")
head = '# GENERATED by cc-P678-tools/art/make_art_layout.py from cc-P237-tools/gen_layout.py (Iron paths, SoS validator).\n'
open(os.path.join(HERE, 'art_gen_layout.py'), 'w', encoding='ascii', newline='\n').write(head + src)
print('wrote art_gen_layout.py')
